    fruit_distribution("100 apples and 1 oranges",120) -> 120 - 100 - 1 = 19
    """
    apples = 0
    oranges = 0
    words = s.lower().split()
    for i, word in enumerate(words):
        if word == "apples" and i > 0:
            try:
